head.b:skin:
/*
  ASRBMY Write — Blogger theme
  Dark-teal header, mono navigation, cream grid page, ivory article panel, dark sidebar.
  Change colours in the :root block below (Theme → Edit HTML).
*/
:root{
  --bg:#e9e8d9; --grid:rgba(12,48,45,.07); --header:#0c302d; --header-text:#f4f0e3; --header-muted:#a9c0b8;
  --nav:#0b2c29; --nav-line:rgba(244,240,227,.12); --accent:#b8431f; --accent-strong:#9c3516; --link:#0f5a4f;
  --panel:#f6f2e4; --panel-alt:#efead8; --panel-border:#d3cfba; --text:#1a2724; --muted:#5a6663;
  --side:#0f3431; --side-text:#e8ede6; --side-muted:#9fb5ac; --side-line:rgba(244,240,227,.14);
  --code:#0d2d2a; --max:1240px;
  --head:Georgia,'Times New Roman',serif; --body:Georgia,'Times New Roman',serif;
  --ui:system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif; --mono:ui-monospace,'SFMono-Regular',Menlo,Consolas,monospace;
  color-scheme:light;
}
html[data-theme="dark"]{--bg:#0a1b19;--grid:rgba(244,240,227,.045);--panel:#10231f;--panel-alt:#14302b;--panel-border:#244641;--text:#e7eadf;--muted:#9db2aa;--link:#6fcbb7;--accent:#e0693f;--side:#0d2926;color-scheme:dark}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]){--bg:#0a1b19;--grid:rgba(244,240,227,.045);--panel:#10231f;--panel-alt:#14302b;--panel-border:#244641;--text:#e7eadf;--muted:#9db2aa;--link:#6fcbb7;--accent:#e0693f;--side:#0d2926;color-scheme:dark}}

*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-padding-top:16px}
body{margin:0;min-height:100vh;background:var(--bg);color:var(--text);font:18px/1.75 var(--body);overflow-wrap:break-word;
  background-image:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);background-size:28px 28px}
img{max-width:100%;height:auto}
a{color:var(--link);text-underline-offset:3px}a:hover{color:var(--accent)}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.skip{position:absolute;left:-999px;top:8px;background:#fff;color:#000;padding:8px 14px;z-index:99}.skip:focus{left:8px}
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
.widget{margin:0}
.widget ul{list-style:none;margin:0;padding:0}

/* Header */
.site-header{background:var(--header);color:var(--header-text);
  background-image:repeating-linear-gradient(135deg,rgba(255,255,255,.035) 0 1px,transparent 1px 9px)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:22px;padding-bottom:22px;flex-wrap:wrap}
.brand h1,.brand .brand-title{margin:0;font:800 1.7rem/1.1 var(--ui);letter-spacing:-.01em}
.brand a{color:var(--header-text);text-decoration:none}.brand a:hover{color:#fff}
.brand p{margin:4px 0 0;font:.72rem var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--header-muted)}
.actions{display:flex;gap:10px;align-items:center}
.btn{display:inline-flex;align-items:center;gap:8px;padding:9px 16px;font:600 .74rem var(--mono);letter-spacing:.1em;text-transform:uppercase;text-decoration:none;border:1px solid var(--nav-line);color:var(--header-text);background:transparent;cursor:pointer;border-radius:2px}
.btn:hover{border-color:var(--header-text);color:#fff}
.btn--accent{background:var(--accent);border-color:var(--accent);color:#fff}.btn--accent:hover{background:var(--accent-strong);border-color:var(--accent-strong)}

/* Navigation */
.navbar{background:var(--nav);border-top:1px solid var(--nav-line);border-bottom:3px solid var(--accent)}
.navbar .wrap{display:flex;align-items:stretch}
.menu-btn{display:none;margin:8px 0;background:none;color:var(--header-text);border:1px solid var(--nav-line);padding:9px 14px;font:600 .75rem var(--mono);letter-spacing:.1em;text-transform:uppercase;cursor:pointer}
.navbar .widget{width:100%}
.nav{display:flex;flex-wrap:wrap}
.nav>li{position:relative;border-right:1px solid var(--nav-line)}
.nav>li:last-child{border-right:0}
.nav a{display:block;padding:15px 18px;color:var(--header-text);text-decoration:none;font:600 .78rem var(--mono);letter-spacing:.1em;text-transform:uppercase}
.nav>li:first-child>a{padding-left:0}
.nav a:hover,.nav a[aria-current]{color:#fff;background:rgba(255,255,255,.06)}
.nav li.has-sub>a::after{content:" +";color:var(--accent)}
.nav li.has-sub.open>a::after{content:" −"}
.nav .sub{display:none;position:absolute;left:0;top:100%;min-width:220px;background:var(--nav);border:1px solid var(--nav-line);border-top:3px solid var(--accent);z-index:30}
.nav li.has-sub:hover>.sub,.nav li.has-sub.open>.sub{display:block}
.nav .sub li+li{border-top:1px solid var(--nav-line)}
.nav .sub a{padding:13px 16px}

/* Layout */
.layout{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,3fr);gap:40px;padding-top:36px;padding-bottom:56px;align-items:start}

/* Posts */
.panel{background:var(--panel);border:1px solid var(--panel-border);border-top:4px solid var(--accent);padding:34px 40px;margin-bottom:28px;border-radius:2px}
.kicker{margin:0 0 10px;font:700 .72rem var(--mono);letter-spacing:.14em;text-transform:uppercase}
.kicker a{color:var(--accent);text-decoration:none}
.post-title{margin:0 0 10px;font:var(--head);font-family:var(--head);font-weight:800;font-size:clamp(1.7rem,4.4vw,2.5rem);line-height:1.15;letter-spacing:-.015em}
.post-title a{color:var(--text);text-decoration:none}.post-title a:hover{color:var(--accent)}
.meta{margin:0 0 18px;font:.78rem var(--mono);letter-spacing:.04em;color:var(--muted);text-transform:uppercase}
.meta span+span::before{content:" · "}
.excerpt{margin:0 0 14px;color:var(--muted)}
.readmore{font:700 .76rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--accent);text-decoration:none}
.thumb{display:block;margin:0 0 18px}.thumb img{display:block;width:100%;max-height:340px;object-fit:cover}
.post-body{font-size:var(--reading,18px)}
.post-body h1,.post-body h2,.post-body h3,.post-body h4{font-family:var(--head);font-weight:800;line-height:1.2;margin:1.8em 0 .5em}
.post-body h2{font-size:1.65rem;border-bottom:1px solid var(--panel-border);padding-bottom:.25em}
.post-body h3{font-size:1.3rem}
.post-body blockquote{margin:1.5em 0;padding:.4em 1.3em;border-left:4px solid var(--accent);background:var(--panel-alt);font-style:italic}
.post-body table{border-collapse:collapse;width:100%;display:block;overflow-x:auto}
.post-body th,.post-body td{border:1px solid var(--panel-border);padding:10px 14px;text-align:left}
.post-body th{background:var(--panel-alt)}
.post-body :not(pre)>code{font:.88em var(--mono);background:var(--panel-alt);padding:.1em .35em;border-radius:2px}
.post-body .separator a{margin:0!important}
.code-block{position:relative;margin:1.6em 0;background:var(--code);border-radius:2px;overflow:hidden}
.code-block pre{margin:0;padding:36px 18px 16px;overflow-x:auto;font:.86rem/1.65 var(--mono);color:#e6ede7;white-space:pre}
.code-block pre code{background:none;padding:0;font:inherit}
.code-copy{position:absolute;top:6px;right:6px;background:rgba(255,255,255,.1);color:#e6ede7;border:0;padding:4px 10px;font:600 .68rem var(--mono);letter-spacing:.08em;text-transform:uppercase;cursor:pointer;border-radius:2px}
.code-copy:hover{background:var(--accent)}
.toc{margin:0 0 28px;padding:16px 20px;background:var(--panel-alt);border:1px solid var(--panel-border);font:.92rem/1.5 var(--ui)}
.toc strong{display:block;margin-bottom:6px;font:700 .72rem var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.toc ol{margin:0;padding-left:1.2em}.toc li{margin:3px 0}.toc li.sub{margin-left:1em;list-style:circle}
.post-labels{margin:28px 0 0;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.post-labels a{font:600 .72rem var(--mono);letter-spacing:.08em;text-transform:uppercase;text-decoration:none;border:1px solid var(--panel-border);padding:5px 11px;color:var(--text);border-radius:2px}
.post-labels a:hover{border-color:var(--accent);color:var(--accent)}
.share{margin:20px 0 0;font:.78rem var(--mono);letter-spacing:.06em;text-transform:uppercase}
.share a{margin-right:14px}
.pager{display:flex;justify-content:space-between;gap:12px;margin:8px 0 0;flex-wrap:wrap}
.pager a{flex:1 1 200px;text-align:center;padding:14px 18px;background:var(--panel);border:1px solid var(--panel-border);font:700 .76rem var(--mono);letter-spacing:.1em;text-transform:uppercase;text-decoration:none;color:var(--text)}
.pager a:hover{border-color:var(--accent);color:var(--accent)}
.status{padding:12px 16px;margin:0 0 20px;background:var(--panel-alt);border-left:4px solid var(--accent);font:.85rem var(--mono)}
.comments{margin-top:34px;padding-top:22px;border-top:1px solid var(--panel-border)}
.comments h3{margin:0 0 12px;font:700 .8rem var(--mono);letter-spacing:.14em;text-transform:uppercase}
.comments iframe{width:100%;min-height:340px;border:0}

/* Sidebar */
.sidebar{background:var(--side);color:var(--side-text);padding:8px 26px 26px;border-top:4px solid var(--accent);border-radius:2px;font:.95rem/1.55 var(--ui)}
.sidebar a{color:var(--side-text);text-decoration:none}.sidebar a:hover{color:#ffb299}
.side-block{padding:20px 0;border-bottom:1px solid var(--side-line)}.side-block:last-child{border-bottom:0}
.sidebar h3,.sidebar .side-title{margin:0 0 12px;font:700 .74rem var(--mono);letter-spacing:.16em;text-transform:uppercase;color:var(--side-muted)}
.sidebar li{padding:8px 0;border-top:1px solid var(--side-line)}.sidebar li:first-child{border-top:0}
.sidebar .count{float:right;color:var(--side-muted);font:.75rem var(--mono)}
.promo{border-left:4px solid var(--accent);padding-left:16px}
.promo h2{margin:0 0 6px;font:800 1.15rem var(--ui)}.promo p{margin:0 0 12px;color:var(--side-muted)}
.side-search{display:flex}
.side-search input{flex:1;min-width:0;padding:10px 12px;border:1px solid var(--side-line);background:#f6f2e4;color:#1a2724;font:16px var(--ui);border-radius:2px 0 0 2px}
.side-search button{padding:0 16px;border:0;background:var(--accent);color:#fff;font:700 .74rem var(--mono);letter-spacing:.1em;text-transform:uppercase;cursor:pointer;border-radius:0 2px 2px 0}
.side-search button:hover{background:var(--accent-strong)}
.quote{font:italic 1rem/1.6 var(--head);color:var(--side-text)}.quote cite{display:block;margin-top:8px;font:700 .72rem var(--mono);font-style:normal;letter-spacing:.12em;text-transform:uppercase;color:var(--side-muted)}

/* Footer */
.footer{background:var(--header);color:var(--header-muted);font:.85rem/1.6 var(--ui);border-top:3px solid var(--accent)}
.footer .wrap{padding-top:28px;padding-bottom:28px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
.footer a{color:var(--header-text)}
.footer .widget{margin:0}

/* Blogger extras */
.blog-feeds,.post-feeds,.feed-links{display:none}
#navbar-iframe,.Navbar{display:none!important}

/* Responsive */
@media (max-width:1000px){.layout{grid-template-columns:minmax(0,1fr)}}
@media (max-width:860px){
  .menu-btn{display:inline-block}
  .navbar .wrap{flex-direction:column}
  .nav{display:none;flex-direction:column;padding-bottom:8px}
  body.nav-open .nav{display:flex}
  .nav>li{border-right:0;border-bottom:1px solid var(--nav-line)}
  .nav>li:first-child>a{padding-left:18px}
  .nav .sub{position:static;border:0;border-left:3px solid var(--accent);margin:0 0 8px 18px;min-width:0}
  .nav li.has-sub:hover>.sub{display:none}.nav li.has-sub.open>.sub{display:block}
}
@media (max-width:640px){
  body{font-size:17px}.wrap{padding:0 16px}
  .panel{padding:22px 18px}
  .site-header .wrap{padding-top:16px;padding-bottom:16px}
  .actions .btn{padding:8px 11px}
  .sidebar{padding:4px 18px 18px}
}
@media print{.site-header,.navbar,.sidebar,.footer,.pager,.share,.code-copy{display:none}body{background:#fff}.panel{border:0;padding:0}}

body.script:
//
(function () {
  'use strict';
  var root = document.documentElement;
  function $(s, c) { return (c || document).querySelector(s); }
  function $$(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }
  function store(k, v) { try { if (v === undefined) return localStorage.getItem(k); localStorage.setItem(k, v); } catch (e) {} }

  var y = $('#year'); if (y) y.textContent = new Date().getFullYear();

  // Theme toggle
  var tb = $('#theme-toggle');
  function sync() { if (tb) tb.setAttribute('aria-pressed', String(root.getAttribute('data-theme') === 'dark')); }
  if (!root.getAttribute('data-theme') && window.matchMedia) root.setAttribute('data-theme', matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  sync();
  if (tb) tb.addEventListener('click', function () {
    var n = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', n); store('asrbmy-theme', n); sync();
  });

  // Menu: a link whose name starts with "_" becomes a sub-menu item of the link above it (use "_Name" in Layout → Menu)
  var nav = $('#site-nav');
  if (nav) {
    var last = null, here = location.pathname;
    $$('li', nav).forEach(function (li) {
      var a = $('a', li), name = a.textContent.trim();
      if (name.charAt(0) === '_' && last) {
        a.textContent = name.replace(/^_+\s*/, '');
        var sub = $('.sub', last);
        if (!sub) {
          sub = document.createElement('ul'); sub.className = 'sub'; last.appendChild(sub); last.classList.add('has-sub');
          last.addEventListener('click', function (e) { if (innerWidth <= 860 && e.target.closest('a') === $('a', this) && $('.sub', this)) { e.preventDefault(); this.classList.toggle('open'); } });
        }
        sub.appendChild(li);
      } else { last = li; }
    });
    $$('a', nav).forEach(function (a) { try { if (new URL(a.href).pathname === here) a.setAttribute('aria-current', 'page'); } catch (e) {} });
  }
  var mb = $('#menu-btn');
  if (mb) mb.addEventListener('click', function () {
    var open = document.body.classList.toggle('nav-open'); mb.setAttribute('aria-expanded', String(open));
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { document.body.classList.remove('nav-open'); if (mb) mb.setAttribute('aria-expanded', 'false'); } });

  // Reading time on every post
  $$('.post').forEach(function (p) {
    var body = $('.post-body', p), el = $('.read-time', p), text = body ? body.textContent : (($('.excerpt', p) || {}).textContent || '');
    if (el && body) { var m = Math.max(1, Math.round(text.trim().split(/\s+/).length / 220)); el.textContent = m + ' min read'; }
  });

  // Article page: table of contents, code blocks
  var body = $('.post-body');
  if (body) {
    var hs = $$('h2, h3', body);
    if (hs.length >= 3) {
      var ol = document.createElement('ol'), used = {};
      hs.forEach(function (h, i) {
        var id = h.id || (h.textContent.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'section-' + i);
        if (used[id]) id += '-' + i; used[id] = 1; h.id = id;
        var li = document.createElement('li'), a = document.createElement('a');
        a.href = '#' + id; a.textContent = h.textContent; li.appendChild(a);
        if (h.tagName === 'H3') li.className = 'sub'; ol.appendChild(li);
      });
      var toc = document.createElement('nav'); toc.className = 'toc'; toc.setAttribute('aria-label', 'Table of contents');
      toc.innerHTML = '<strong>On this page</strong>'; toc.appendChild(ol); body.insertBefore(toc, body.firstChild);
    }
    $$('pre', body).forEach(function (pre) {
      if (pre.parentNode.className === 'code-block') return;
      var wrap = document.createElement('div'); wrap.className = 'code-block';
      pre.parentNode.insertBefore(wrap, pre); wrap.appendChild(pre);
      if (!pre.querySelector('code')) { var c = document.createElement('code'); c.textContent = pre.textContent; pre.textContent = ''; pre.appendChild(c); }
      if (window.hljs) { try { window.hljs.highlightElement(pre.querySelector('code')); } catch (e) {} }
      var b = document.createElement('button'); b.type = 'button'; b.className = 'code-copy'; b.textContent = 'Copy'; b.setAttribute('aria-label', 'Copy code to clipboard');
      b.addEventListener('click', function () {
        var txt = pre.textContent;
        (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject()).then(function () { b.textContent = 'Copied'; }, function () {
          var ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select();
          try { document.execCommand('copy'); b.textContent = 'Copied'; } catch (e) { b.textContent = 'Press Ctrl+C'; } ta.remove();
        });
        setTimeout(function () { b.textContent = 'Copy'; }, 1800);
      });
      wrap.appendChild(b);
    });
  }
})();
//
